/**
 * Qwen21ImageToImageRequest
 */
export type Qwen21ImageToImageRequest = {
    /**
     * Prompt
     *
     * The prompt describing the result you want. When mask_url is supplied, describe what should be generated inside the white area of the mask.
     */
    prompt: string;
    /**
     * Images List
     *
     * Reference images, 1 to 10 URLs. Order matters when the prompt refers to 'the first image', 'the second image', etc.
     */
    images_list: Array<string>;
    /**
     * Mask Url
     *
     * Inpainting mask (white = area to change, black = kept unchanged) that switches the request into local-edit mode. Must be used with exactly one reference image.
     */
    mask_url?: string | null;
    /**
     * Aspect Ratio
     *
     * Output image aspect ratio. Defaults to the first reference image's ratio. Ignored in local-edit mode.
     */
    aspect_ratio?: 'auto' | '1:1' | '4:3' | '3:4' | '3:2' | '2:3' | '16:9' | '9:16' | '21:9' | '9:21' | null;
    /**
     * Resolution
     *
     * Output resolution tier. 2K produces four times the pixels and takes longer.
     */
    resolution?: '1K' | '2K' | null;
    /**
     * Background
     *
     * Background type. Transparent outputs a PNG/WebP with an alpha channel; describe only the subject when using it.
     */
    background?: 'opaque' | 'transparent' | null;
    /**
     * Output Format
     *
     * Output image format. JPEG has no alpha channel and cannot be combined with a transparent background.
     */
    output_format?: 'jpeg' | 'png' | 'webp' | null;
    /**
     * Enhance Prompt
     *
     * Rewrites the prompt into a fuller scene description before generating, improving quality.
     */
    enhance_prompt?: boolean | null;
    /**
     * Seed
     *
     * Random seed. Omit to generate with a random seed.
     */
    seed?: number | null;
    /**
     * Webhook Url
     */
    webhook_url?: string | null;
};

